  public static func endQRP(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createQRP(
    _ fbb: inout FlatBufferBuilder,
    KIND: qrpKind = .request,
    STATUS: qrpStatus = .ok,
    ERROR_CODEOffset ERROR_CODE: Offset = Offset(),
    MESSAGEOffset MESSAGE: Offset = Offset(),
    RETRY_AFTER_MS: UInt32 = 0,
    SCHEMA_NAMEOffset SCHEMA_NAME: Offset = Offset(),
    FILE_IDENTIFIEROffset FILE_IDENTIFIER: Offset = Offset(),
    SQLOffset SQL: Offset = Offset(),
    SEARCHOffset SEARCH: Offset = Offset(),
    FILTERSVectorOffset FILTERS: Offset = Offset(),
    SORT_FIELDOffset SORT_FIELD: Offset = Offset(),
    SORT_DESC: Bool = false,
    PROVIDER_IDOffset PROVIDER_ID: Offset = Offset(),
    SOURCE_NAMEOffset SOURCE_NAME: Offset = Offset(),
    BATCH_IDOffset BATCH_ID: Offset = Offset(),
    PRODUCER_PEER_IDOffset PRODUCER_PEER_ID: Offset = Offset(),
    ORIGIN_IDOffset ORIGIN_ID: Offset = Offset(),
    FROM_EPOCH_MS: Int64 = 0,
    TO_EPOCH_MS: Int64 = 0,
    PAGE: UInt32 = 0,
    LIMIT: UInt32 = 0,
    CURSOROffset CURSOR: Offset = Offset(),
    NEXT_CURSOROffset NEXT_CURSOR: Offset = Offset(),
    RECORD_COUNT: UInt32 = 0,
    TOTAL_COUNT: UInt64 = 0,
    SCANNED: UInt64 = 0,
    STORED: UInt64 = 0,
    PARTIAL: Bool = false,
    TRUNCATED: Bool = false,
    AS_OF_MS: Int64 = 0,
    STALE: Bool = false,
    ELAPSED_MS: UInt32 = 0,
    GENERATED_AT_MS: Int64 = 0,
    ETAGOffset ETAG: Offset = Offset(),
    CIDOffset CID: Offset = Offset(),
    ARCHIVE_IDOffset ARCHIVE_ID: Offset = Offset(),
    COLUMNSVectorOffset COLUMNS: Offset = Offset()
  ) -> Offset {
    let __start = QRP.startQRP(&fbb)
    QRP.add(KIND: KIND, &fbb)
    QRP.add(STATUS: STATUS, &fbb)
    QRP.add(ERROR_CODE: ERROR_CODE, &fbb)
    QRP.add(MESSAGE: MESSAGE, &fbb)
    QRP.add(RETRY_AFTER_MS: RETRY_AFTER_MS, &fbb)
    QRP.add(SCHEMA_NAME: SCHEMA_NAME, &fbb)
    QRP.add(FILE_IDENTIFIER: FILE_IDENTIFIER, &fbb)
    QRP.add(SQL: SQL, &fbb)
    QRP.add(SEARCH: SEARCH, &fbb)
    QRP.addVectorOf(FILTERS: FILTERS, &fbb)
    QRP.add(SORT_FIELD: SORT_FIELD, &fbb)
    QRP.add(SORT_DESC: SORT_DESC, &fbb)
    QRP.add(PROVIDER_ID: PROVIDER_ID, &fbb)
    QRP.add(SOURCE_NAME: SOURCE_NAME, &fbb)
    QRP.add(BATCH_ID: BATCH_ID, &fbb)
    QRP.add(PRODUCER_PEER_ID: PRODUCER_PEER_ID, &fbb)
    QRP.add(ORIGIN_ID: ORIGIN_ID, &fbb)
    QRP.add(FROM_EPOCH_MS: FROM_EPOCH_MS, &fbb)
    QRP.add(TO_EPOCH_MS: TO_EPOCH_MS, &fbb)
    QRP.add(PAGE: PAGE, &fbb)
    QRP.add(LIMIT: LIMIT, &fbb)
    QRP.add(CURSOR: CURSOR, &fbb)
    QRP.add(NEXT_CURSOR: NEXT_CURSOR, &fbb)
    QRP.add(RECORD_COUNT: RECORD_COUNT, &fbb)
    QRP.add(TOTAL_COUNT: TOTAL_COUNT, &fbb)
    QRP.add(SCANNED: SCANNED, &fbb)
    QRP.add(STORED: STORED, &fbb)
    QRP.add(PARTIAL: PARTIAL, &fbb)
    QRP.add(TRUNCATED: TRUNCATED, &fbb)
    QRP.add(AS_OF_MS: AS_OF_MS, &fbb)
    QRP.add(STALE: STALE, &fbb)
    QRP.add(ELAPSED_MS: ELAPSED_MS, &fbb)
    QRP.add(GENERATED_AT_MS: GENERATED_AT_MS, &fbb)
    QRP.add(ETAG: ETAG, &fbb)
    QRP.add(CID: CID, &fbb)
    QRP.add(ARCHIVE_ID: ARCHIVE_ID, &fbb)
    QRP.addVectorOf(COLUMNS: COLUMNS, &fbb)
    return QRP.endQRP(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.KIND, fieldName: "KIND", required: false, type: qrpKind.self)
    try _v.visit(field: VT.STATUS, fieldName: "STATUS", required: false, type: qrpStatus.self)
    try _v.visit(field: VT.ERROR_CODE, fieldName: "ERROR_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.MESSAGE, fieldName: "MESSAGE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.RETRY_AFTER_MS, fieldName: "RETRY_AFTER_MS", required: false, type: UInt32.self)
    try _v.visit(field: VT.SCHEMA_NAME, fieldName: "SCHEMA_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FILE_IDENTIFIER, fieldName: "FILE_IDENTIFIER", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SQL, fieldName: "SQL", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SEARCH, fieldName: "SEARCH", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FILTERS, fieldName: "FILTERS", required: false, type: ForwardOffset<Vector<ForwardOffset<QRPFilter>, QRPFilter>>.self)
