    try _v.visit(field: VT.SORT_DESC, fieldName: "SORT_DESC", required: false, type: Bool.self)
    try _v.visit(field: VT.PROVIDER_ID, fieldName: "PROVIDER_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SOURCE_NAME, fieldName: "SOURCE_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.BATCH_ID, fieldName: "BATCH_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PRODUCER_PEER_ID, fieldName: "PRODUCER_PEER_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ORIGIN_ID, fieldName: "ORIGIN_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FROM_EPOCH_MS, fieldName: "FROM_EPOCH_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.TO_EPOCH_MS, fieldName: "TO_EPOCH_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.PAGE, fieldName: "PAGE", required: false, type: UInt32.self)
    try _v.visit(field: VT.LIMIT, fieldName: "LIMIT", required: false, type: UInt32.self)
    try _v.visit(field: VT.CURSOR, fieldName: "CURSOR", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.NEXT_CURSOR, fieldName: "NEXT_CURSOR", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.RECORD_COUNT, fieldName: "RECORD_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.TOTAL_COUNT, fieldName: "TOTAL_COUNT", required: false, type: UInt64.self)
    try _v.visit(field: VT.SCANNED, fieldName: "SCANNED", required: false, type: UInt64.self)
    try _v.visit(field: VT.STORED, fieldName: "STORED", required: false, type: UInt64.self)
    try _v.visit(field: VT.PARTIAL, fieldName: "PARTIAL", required: false, type: Bool.self)
    try _v.visit(field: VT.TRUNCATED, fieldName: "TRUNCATED", required: false, type: Bool.self)
    try _v.visit(field: VT.AS_OF_MS, fieldName: "AS_OF_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.STALE, fieldName: "STALE", required: false, type: Bool.self)
    try _v.visit(field: VT.ELAPSED_MS, fieldName: "ELAPSED_MS", required: false, type: UInt32.self)
    try _v.visit(field: VT.GENERATED_AT_MS, fieldName: "GENERATED_AT_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.ETAG, fieldName: "ETAG", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CID, fieldName: "CID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ARCHIVE_ID, fieldName: "ARCHIVE_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COLUMNS, fieldName: "COLUMNS", required: false, type: ForwardOffset<Vector<ForwardOffset<QRPColumn>, QRPColumn>>.self)
    _v.finish()
  }
